/* DeliveryChgMapper.selectDeliveryDocList : 배송지변경신고 제출번호 그룹 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT edi.EDI_DOC_NO ,MAX(edi.EDI_SEND_DATE) AS EDI_SEND_DATE ,MAX(edi.REGISTER_DATE_TIME) AS REGISTER_DATE_TIME ,MAX(edi.BOUND) AS BOUND ,(SELECT count(*) FROM TB_ECM_OD_ADDITIONAL odAdd WHERE edi.EDI_DOC_NO = odAdd.DELIVERY_DOC_NO ) AS DOC_CNT ,MAX(edi.EDI_STATUS) AS EDI_STATUS ,MAX(edi.EDI_PORTAL_MAILBOX_ID) AS EDI_PORTAL_MAILBOX_ID ,SUM(CASE WHEN edi.EDI_STATUS IN ('READY','SEND','RECV','1','2','3','4') THEN 1 ELSE 0 END) AS SEND_CNT FROM TB_EDI_LINKED edi WHERE edi.ENT_CODE = #{srchEntCode} AND edi.EDI_CODE = 'GOVCBR109'
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND edi.BOUND = 'AIR' AND edi.BOUND = 'SEA'
AND edi.BOUND_TYPE = 'IMP' GROUP BY edi.EDI_DOC_NO

/* DeliveryChgMapper.selectDeliveryList : 배송지변경신고 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT edi.EDI_JOB_NO ,edi.ENT_CODE ,edi.ENT_BUSINESS_CODE ,od.OD_JOB_NO ,od.BOUND ,od.BOUND_TYPE ,edi.EDI_DOC_NO ,edi.ISSUE_DATE ,edi.EDI_STATUS ,edi.EDI_SEND_DATE ,edi.EDI_RECEIPT_DATE ,edi.EDI_RESULT_DATE ,edi.REGISTER_DATE_TIME AS EDI_REGISTER_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = edi.ENT_CODE AND USER_ID = edi.REGISTER_USER_ID) AS REGISTER_USER_NAME ,odAdd.CLEARANCE_RECEIPT_DATE ,od.PO_NO ,od.CD_TYPE ,od.MBL_NO ,od.HBL_NO ,od.DEST_PORT ,od.MASTER_OD_JOB_NO ,odAdd.DELIVERY_DATE ,CONVERT(VARCHAR(10), odAdd.DELIVERY_DATE, 23) AS DELIVERY_DATE_EXCEL ,od.DELIVERY_NAME_CHANGED ,od.DELIVERY_CODE
,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = od.DELIVERY_CODE) AS DELIVERY_NAME ,CASE WHEN ISNULL(od.CONSIGNEE_ADDRESS_LOC, '') = '' THEN CONCAT(ISNULL(od.CONSIGNEE_ADDRESS, ''), ISNULL(od.CONSIGNEE_ADDRESS_A, ''), ISNULL(od.CONSIGNEE_ADDRESS_B, ''), ISNULL(od.CONSIGNEE_ADDRESS_C, ''), ISNULL(od.CONSIGNEE_ADDRESS_D, '')) ELSE od.CONSIGNEE_ADDRESS_LOC END AS CONSIGNEE_ADDRESS ,CONSIGNEE_ADDRESS_LOC ,od.DELIVERY_ADDRESS_CHANGED ,od.DELIVERY_REASON_CHANGED ,od.CONSIGNEE_NAME ,od.COMMODITY_ITEM ,od.CUSTOMS_CODE ,od.ORIG_CODE ,od.VESSEL_FLIGHT ,odAdd.SIMPLE_REPORT_DATE ,odAdd.SIMPLE_DOC_NO ,odAdd.DELIVERY_CHANGED_SEQ_NO ,edi.REGISTER_DATE_TIME ,od.PENALTY_YN ,od.DELIVERY_CHANGE_DATE_TIME
,(SELECT EDI_PORTAL_MAILBOX_ID FROM TB_SMS_ENT_BUS_EDI_ECM WHERE ENT_CODE = od.ENT_CODE AND SEQ_NO = odAdd.EDI_MAILBOX_SEQ_NO) AS EDI_PORTAL_MAILBOX_ID
FROM TB_ECM_OD od
WITH (INDEX(TB_ECM_OD_X02)) WITH (INDEX(TB_ECM_OD_X06_TY_TP))
LEFT OUTER JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO LEFT OUTER JOIN TB_EDI_LINKED edi ON edi.EDI_DOC_NO = odAdd.DELIVERY_DOC_NO WHERE od.ENT_CODE = #{srchEntCode} AND od.CONSOL_YN = 'Y' AND (ISNULL(od.DELIVERY_ADDRESS_CHANGED,'') <> '' OR ISNULL(od.DELIVERY_NAME_CHANGED,'') <> '')
AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'
AND edi.EDI_JOB_NO IS NULL
AND edi.EDI_JOB_NO IS NOT NULL
AND od.CD_TYPE = #{srchCdType}
AND od.HBL_NO = #{srchNoHouse}
AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND (edi.EDI_STATUS IS NOT NULL AND edi.EDI_STATUS <> '')
AND (edi.EDI_STATUS IS NULL OR edi.EDI_STATUS = '')
AND od.CUSTOMS_CODE = #{srchCustomsCode}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND edi.EDI_DOC_NO = #{ediDocNo}
AND edi.EDI_DOC_NO IN (
#{item.ediDocNo}
)
AND od.OD_JOB_NO IN (
#{item.odJobNo}
)

