/* DeliveryChgMapper.insertDeliveryChg : 배송지변경신고 insert */
INSERT INTO TB_EDI_LINKED(
	EDI_JOB_NO
	,ENT_CODE
	,ENT_BUSINESS_CODE
	,OD_JOB_NO
	,BOUND
	,BOUND_TYPE
	,EDI_CODE
	,EDI_DOC_NO
	,ISSUE_DATE	
	,EDI_STATUS
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
	,EDI_PORTAL_MAILBOX_ID
)VALUES(
	 #{ediJobNo}
	,#{entCode}
	,#{entBusinessCode}
	,#{masterOdJobNo}
	,#{bound}
	,#{boundType}
	,'GOVCBR109'
	,#{ediDocNo}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())
	,'EDI'
	,#{registerUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())
	,#{ediPortalMailboxId}
)

/* DeliveryChgMapper.updateDeliveryJob : 배송지변경신고 insert */
UPDATE TB_ECM_OD_ADDITIONAL
SET DELIVERY_DOC_NO = #{ediDocNo}
WHERE OD_JOB_NO = #{odJobNo}

