/* DeliveryChgMapper.selectEdiSendChk : 배송지변경신고 전송유무 체크 */
SELECT COUNT(od.OD_JOB_NO) AS CNT FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO INNER JOIN TB_EDI_LINKED edi ON edi.EDI_DOC_NO = ad.DELIVERY_DOC_NO WHERE (
( od.HBL_NO = #{item.hblNo}
AND od.MBL_NO = #{item.mblNo}
)
) AND edi.EDI_SEND_DATE IS NOT NULL
SELECT COUNT(ad.OD_JOB_NO) AS CNT FROM TB_ECM_OD_ADDITIONAL ad INNER JOIN TB_EDI_LINKED edi ON edi.EDI_DOC_NO = ad.DELIVERY_DOC_NO WHERE ad.OD_JOB_NO IN(#{item.odJobNo}) AND edi.EDI_SEND_DATE IS NOT NULL
SELECT COUNT(EDI_JOB_NO) AS CNT FROM TB_EDI_LINKED WHERE ISNULL(EDI_STATUS, '') NOT IN ('', 'EXCEL', 'EDI', 'ERROR') AND EDI_DOC_NO IN(#{item.ediDocNo})
SELECT COUNT(EDI_JOB_NO) AS CNT FROM TB_EDI_LINKED WHERE EDI_SEND_DATE IS NOT NULL AND EDI_DOC_NO IN(#{item.ediDocNo})

/* DeliveryChgMapper.selectEdiSendChk2 : 배송지변경신고 전송유무 체크2 */
SELECT od.HBL_NO FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO INNER JOIN TB_EDI_LINKED edi ON edi.EDI_DOC_NO = ad.DELIVERY_DOC_NO WHERE (
( od.HBL_NO = LTRIM(RTRIM(#{item.hblNo}))
AND od.MBL_NO = LTRIM(RTRIM(#{item.mblNo}))
)
) AND edi.EDI_SEND_DATE IS NOT NULL
SELECT od.HBL_NO FROM TB_ECM_OD_ADDITIONAL ad INNER JOIN TB_EDI_LINKED edi ON edi.EDI_DOC_NO = ad.DELIVERY_DOC_NO WHERE ad.OD_JOB_NO IN(#{item.odJobNo}) AND edi.EDI_SEND_DATE IS NOT NULL
SELECT od.HBL_NO FROM TB_EDI_LINKED WHERE ISNULL(EDI_STATUS, '') NOT IN ('', 'EXCEL', 'EDI', 'ERROR') AND EDI_DOC_NO IN(#{item.ediDocNo})
SELECT od.HBL_NO FROM TB_EDI_LINKED WHERE EDI_SEND_DATE IS NOT NULL AND EDI_DOC_NO IN(#{item.ediDocNo})

mapper.insert:
/* DeliveryChgMapper.updateBatchDeliveryChg : 배송지변경신고 update */

UPDATE TB_ECM_OD SET
	  UPDATE_USER_ID = #{updateUserId}
	  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	  
	  , DELIVERY_REASON_CHANGED = #{deliveryReasonChanged}
	  
	  
	  ,DELIVERY_NAME_CHANGED = #{deliveryNameChanged}
	  
	  
	  ,DELIVERY_ADDRESS_CHANGED = #{deliveryAddressChanged}
	  			  
	  
	  
	  ,DELIVERY_CHANGE_DATE_TIME = CASE WHEN DELIVERY_CHANGE_DATE_TIME IS NULL THEN DATEADD(HOUR, ${gmtTime}, GETDATE()) ELSE DELIVERY_CHANGE_DATE_TIME END
	  
	  
	  ,DELIVERY_CHANGE_DATE_TIME = NULL
	  ,DELIVERY_REASON_CHANGED = NULL
	  ,DELIVERY_NAME_CHANGED = NULL
	  ,DELIVERY_ADDRESS_CHANGED = NULL
	  
	  
WHERE OD_JOB_NO = #{item.odJobNo};

UPDATE TB_ECM_OD_ADDITIONAL SET
	   
	   
	   DELIVERY_DATE = CONVERT(DATE, #{deliveryDate}, ${dateFormat})
	  ,DELIVERY_YN = 'Y'
	  ,LAST_POD_STATUS = CASE WHEN ISNULL(LAST_POD_STATUS, '') < 'ECM420' THEN 'ECM420' ELSE LAST_POD_STATUS END
	  
	   
	   
	   DELIVERY_DATE = NULL
	  ,DELIVERY_YN = 'N'
	   
	   
WHERE OD_JOB_NO = #{item.odJobNo};

