/* DeliveryChgMapper.deleteBatchDeliveryChg : 배송지변경신고 delete */
		
	DELETE TB_EDI_LINKED 				
	WHERE EDI_DOC_NO = #{item.ediDocNo};
	UPDATE TB_ECM_OD_ADDITIONAL 	
	SET DELIVERY_DOC_NO = ''
	WHERE DELIVERY_DOC_NO = #{item.ediDocNo};

mapper.select:
/* DeliveryChgMapper.selectHblValidate : hbl유효성체크 */
WITH TMP AS( SELECT A.ENT_CODE, A.HBL_NO FROM (
SELECT #{entCode} AS ENT_CODE,#{item.mblNo} AS MBL_NO ,#{item.hblNo} AS HBL_NO
) A LEFT JOIN TB_ECM_OD OD ON OD.ENT_CODE = #{entCode} AND A.MBL_NO = OD.MBL_NO AND A.HBL_NO = OD.HBL_NO WHERE OD.OD_JOB_NO IS NULL )
WITH TMP AS( SELECT A.ENT_CODE, A.HBL_NO FROM (
SELECT #{entCode} AS ENT_CODE, #{item.MBL_NO} AS EXCEL_MBL_NO ,#{item.HBL_NO} AS HBL_NO
) A LEFT JOIN TB_ECM_OD OD ON OD.ENT_CODE = A.ENT_CODE AND OD.HBL_NO = A.HBL_NO AND ( (OD.MBL_NO = A.EXCEL_MBL_NO) OR (ISNULL(OD.MBL_NO, '') = '' AND ISNULL(A.EXCEL_MBL_NO, '') = '') ) WHERE OD.OD_JOB_NO IS NULL )
WITH TMP AS( SELECT A.ENT_CODE, A.HBL_NO FROM (
SELECT #{entCode} AS ENT_CODE,#{item.HBL_NO} AS HBL_NO
) A LEFT JOIN TB_ECM_OD OD ON OD.ENT_CODE = #{entCode} AND A.HBL_NO = OD.HBL_NO WHERE OD.OD_JOB_NO IS NULL )
WITH TMP AS( SELECT A.ENT_CODE, A.MBL_NO, A.HBL_NO FROM (
SELECT #{entCode} AS ENT_CODE, #{item.MBL_NO} AS MBL_NO, #{item.HBL_NO} AS HBL_NO
) A LEFT JOIN TB_ECM_OD OD ON OD.ENT_CODE = #{entCode} AND A.MBL_NO = OD.MBL_NO AND A.HBL_NO = OD.HBL_NO AND OD.BOUND = 'SEA' AND OD.BOUND_TYPE = 'IMP' WHERE OD.OD_JOB_NO IS NULL )
WITH TMP AS( SELECT A.ENT_CODE, A.MBL_NO FROM (
SELECT #{entCode} AS ENT_CODE, #{item.MBL_NO} AS MBL_NO
) A LEFT JOIN TB_ECM_OD OD ON OD.ENT_CODE = #{entCode} AND A.MBL_NO = OD.MBL_NO AND OD.BOUND = 'SEA' AND OD.BOUND_TYPE = 'IMP' WHERE OD.OD_JOB_NO IS NULL )
WITH TMP AS( SELECT A.ENT_CODE, A.HBL_NO FROM (
SELECT #{entCode} AS ENT_CODE,#{item.HBL_NO} AS HBL_NO
) A LEFT JOIN TB_ECM_OD OD ON OD.ENT_CODE = #{entCode} AND A.HBL_NO = OD.HBL_NO AND OD.BOUND = 'SEA' AND OD.BOUND_TYPE = 'IMP' WHERE OD.OD_JOB_NO IS NULL )
WITH TMP AS( SELECT A.ENT_CODE, A.HBL_NO FROM (
SELECT #{entCode} AS ENT_CODE,#{item.HBL_NO} AS HBL_NO
) A LEFT JOIN TB_ECM_OD OD ON OD.ENT_CODE = #{entCode} AND A.HBL_NO = OD.HBL_NO LEFT JOIN TB_ECM_OD_MULTI MULTI ON A.HBL_NO = MULTI.DELIVERY_NO WHERE OD.OD_JOB_NO IS NULL AND MULTI.OD_JOB_NO IS NULL )
SELECT COUNT(t.MBL_NO) AS NOT_BL_CNT , STUFF((SELECT ', ' + MBL_NO FROM TMP WHERE ENT_CODE = t.ENT_CODE FOR XML PATH('')), 1, 2, '') AS NOT_HBL_LIST FROM TMP t GROUP BY t.ENT_CODE
SELECT COUNT(t.HBL_NO) AS NOT_BL_CNT , STUFF((SELECT ', ' + HBL_NO FROM TMP WHERE ENT_CODE = t.ENT_CODE FOR XML PATH('')), 1, 2, '') AS NOT_HBL_LIST FROM TMP t GROUP BY t.ENT_CODE

/* DeliveryChgMapper.selectHblValidate2 : hbl유효성체크 */ SELECT excel.ENT_CODE ,excel.HBL_NO ,od.OD_JOB_NO ,od.MASTER_OD_JOB_NO ,od.MBL_NO ,ad.LAST_POD_STATUS FROM(
SELECT #{entCode} AS ENT_CODE, #{item.MBL_NO} AS MBL_NO ,#{item.HBL_NO} AS HBL_NO
) excel LEFT JOIN TB_ECM_OD od ON od.MBL_NO = excel.MBL_NO AND od.HBL_NO = excel.HBL_NO LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO

mapper.insert:
/* DeliveryChgMapper.updateExcelDeliveryChg : 배송지변경신고 Excel update */

UPDATE TB_ECM_OD SET
	 UPDATE_USER_ID = #{updateUserId}
	 ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	
	 ,DELIVERY_NAME_CHANGED = #{item.deliveryNameChanged}	
	
	
	,DELIVERY_ADDRESS_CHANGED = #{item.deliveryAddressChanged}
	
	
	,DELIVERY_REASON_CHANGED = #{item.deliveryReasonChanged}
	
	
	,DELIVERY_CHANGE_DATE_TIME = CASE WHEN DELIVERY_CHANGE_DATE_TIME IS NULL OR DELIVERY_CHANGE_DATE_TIME = '1900-01-01 00:00:00' 
		THEN DATEADD(HOUR, ${gmtTime}, GETDATE()) ELSE DELIVERY_CHANGE_DATE_TIME END
	
WHERE HBL_NO = LTRIM(RTRIM(#{item.hblNo}))

AND MBL_NO = LTRIM(RTRIM(#{item.mblNo}))
;


UPDATE ad SET
	  
	  
	   ad.DELIVERY_DATE = #{item.deliveryDate}
	  ,ad.DELIVERY_YN = 'Y'
	  
	  
FROM TB_ECM_OD od
	 INNER JOIN TB_ECM_OD_ADDITIONAL ad
	 			ON ad.OD_JOB_NO = od.OD_JOB_NO
WHERE od.HBL_NO = LTRIM(RTRIM(#{item.hblNo}))

AND od.MBL_NO = LTRIM(RTRIM(#{item.mblNo}))
;

