/* DeliveryChgMapper.selectDeliveryListTargetCount : 배송지변경신고카운트 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; SELECT od.OD_JOB_NO ,od.DELIVERY_NAME_CHANGED ,od.DELIVERY_ADDRESS_CHANGED ,od.DELIVERY_REASON_CHANGED ,od.DEST_PORT ,od.BOUND ,od.BOUND_TYPE ,od.MASTER_OD_JOB_NO ,edi.EDI_DOC_NO ,(SELECT EDI_PORTAL_MAILBOX_ID FROM TB_SMS_ENT_BUS_EDI_ECM WHERE ENT_CODE = od.ENT_CODE AND SEQ_NO = odAdd.EDI_MAILBOX_SEQ_NO) AS EDI_PORTAL_MAILBOX_ID ,edi.EDI_JOB_NO FROM TB_ECM_OD od
WITH (INDEX(TB_ECM_OD_X02)) WITH (INDEX(TB_ECM_OD_X06_TY_TP))
LEFT OUTER JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO LEFT OUTER JOIN TB_EDI_LINKED edi ON edi.EDI_DOC_NO = odAdd.DELIVERY_DOC_NO WHERE od.ENT_CODE = #{srchEntCode} AND od.CONSOL_YN = 'Y' AND (ISNULL(od.DELIVERY_ADDRESS_CHANGED,'') <> '' OR ISNULL(od.DELIVERY_NAME_CHANGED,'') <> '')
AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'
AND edi.EDI_JOB_NO IS NULL
AND edi.EDI_JOB_NO IS NOT NULL
AND od.CD_TYPE = #{srchCdType}
AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND (edi.EDI_STATUS IS NOT NULL AND edi.EDI_STATUS <> '')
AND (edi.EDI_STATUS IS NULL OR edi.EDI_STATUS = '')
AND od.CUSTOMS_CODE = #{srchCustomsCode}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND edi.EDI_DOC_NO = #{ediDocNo}
AND od.OD_JOB_NO IN (
#{item.odJobNo}
)

/* DeliveryChgMapper.selectOrderList : 배송지변경신고 과태료검증 bl list 조회 */
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
		SELECT
			od.HBL_NO AS hblNo
			,od.MBL_NO AS mblNo
			,od.MASTER_OD_JOB_NO AS masterOdJobNo
			,od.OD_JOB_NO AS odJobNo
			,od.DELIVERY_ADDRESS_CHANGED AS deliveryAddressChanged
			,od.HSN AS hsn
		FROM TB_ECM_OD od 
		LEFT OUTER JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO
		LEFT OUTER JOIN TB_EDI_LINKED edi ON edi.EDI_DOC_NO = odAdd.DELIVERY_DOC_NO
		WHERE od.ENT_CODE = #{srchEntCode}
		AND od.CONSOL_YN = 'Y'
		AND (ISNULL(od.DELIVERY_ADDRESS_CHANGED,'') <> '' OR ISNULL(od.DELIVERY_NAME_CHANGED,'') <> '')
		
		AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP'
		AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'
		
		
				
		AND edi.EDI_JOB_NO IS NULL
		
		
		AND edi.EDI_JOB_NO IS NOT NULL
		
		
		
			AND od.CD_TYPE = #{srchCdType}
		
		
		
			AND od.HBL_NO = #{srchNoHouse}
		
		
		
			
			
			AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
			
			
				
					
					AND ${srchNoType} IN (#{item})
					
					
					AND ${srchNoType} = #{srchNo}
					
				
			
			
		
		
		
			AND (edi.EDI_STATUS IS NOT NULL AND edi.EDI_STATUS <> '')
		
		
			AND (edi.EDI_STATUS IS NULL OR edi.EDI_STATUS = '')
		
		
			AND od.CUSTOMS_CODE = #{srchCustomsCode}
		
		
		AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) 
		
		
			
			
			AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
			
			
			AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
			
			
			
		
		
			AND edi.EDI_DOC_NO = #{ediDocNo}
		
			
		
			AND edi.EDI_DOC_NO IN (
						
							#{item.ediDocNo}
						
						)
		
				
		
		AND od.OD_JOB_NO IN (
						
							#{item.odJobNo}
						
						)
